dataModels.definition:
interface QuotaWindow { pct: number | null; resetSec: number | null }  // null = 无限/未订阅
type QuotaWins = [QuotaWindow, QuotaWindow, QuotaWindow]  // [5h, week, month]
interface NormalizedQuotaRow { label: string; wins: QuotaWins }

// 在 packages/shared/src/provider.ts 的 ProviderInfo 上新增可选字段
interface ProviderInfo {
  // ... 现有字段
  quota?: {
    fetcher: string  // 匹配 QUOTA_PRESETS.fetcher，如 'zhipu' | 'kimi-coding' | 'minimax' | 'mimo' | 'opencode-go'
    enabled: boolean
    cookieSet?: boolean  // cookie 类 provider 的 cookie 是否已写入（api-key 类不需此字段，复用 apiKeySet）
  }
}

// packages/shared/src/quota-presets.ts
interface QuotaPreset {
  fetcher: 'zhipu' | 'opencode-go' | 'kimi-coding' | 'minimax' | 'mimo'
  label: string
  auth: 'api-key' | 'cookie'
  match: { baseUrlPattern?: string; namePattern?: string }
  helpUrl?: string
  helpText?: string
}
const QUOTA_PRESETS: QuotaPreset[] = [/* 5 个内置预设 */]

// packages/renderer/src/stores/quota.ts
interface QuotaState {
  byProvider: Map<string, { data: NormalizedQuotaRow | null; lastFetchAt: number | null }>
  pending: Set<string>  // 正在查询的 providerId 集合（并发保护）
}
